{"command":"python3 - <<'EOF'
import yaml, subprocess, re
for f in ['.github/workflows/build-macos.yml','.github/workflows/build-mobile.yml']:
    doc = yaml.safe_load(open(f))
    n=0
    for job in doc['jobs'].values():
        for step in job.get('steps',[]):
            run = step.get('run','')
            if 'update_git_mirror' in run:
                n+=1
                body = run.replace('${{ github.sha }}','a'*40)
                p = subprocess.run(['bash','-n','-c',body],capture_output=True,text=True)
                print(f, step['name'], 'bash-n rc=', p.returncode, p.stderr.strip()[:200])
                assert p.returncode==0
    print(f,'mirror steps:',n)
EOF"}

